import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] b = a.clone();
        Arrays.sort(b);
        // Survivors start after the last value that exceeds the sum of everything smaller.
        long total = 0, threshold = b[0];
        for (long v : b) {
            if (total < v) threshold = v;
            total += v;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++)
            if (a[i] >= threshold) {
                if (out.length() > 0) out.append(' ');
                out.append(i + 1);
            }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	b := slices.Clone(a)
	slices.Sort(b)
	// Survivors start after the last value that exceeds the sum of everything smaller.
	var total int64
	threshold := b[0]
	for _, v := range b {
		if total < v {
			threshold = v
		}
		total += v
	}
	out := make([]byte, 0, 7*n)
	for i, v := range a {
		if v >= threshold {
			if len(out) > 0 {
				out = append(out, ' ')
			}
			out = strconv.AppendInt(out, int64(i+1), 10)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
